-- Backfill the original prompt catalog. Without this, Turkish clients fall back
-- to the canonical English text even though the app locale is Turkish.
UPDATE "prompts" AS prompt
SET "translations" = COALESCE(prompt."translations", '{}'::JSONB)
  || jsonb_build_object('tr', localized."textTr")
FROM (VALUES
  ('Show us your first beverage of the day.', 'Günün ilk içeceğini bize göster.'),
  ('What does your current workspace look like?', 'Şu anki çalışma alanın nasıl görünüyor?'),
  ('Quick fit check! Show us your outfit of the day.', 'Hızlı bir kombin kontrolü! Bugünkü kıyafetini bize göster.'),
  ('What are you listening to right now? Play a snippet.', 'Şu anda ne dinliyorsun? Kısa bir bölüm çal.'),
  ('Show the absolute best view near you at this moment.', 'Şu anda yakınındaki en güzel manzarayı göster.'),
  ('Introduce your favorite pet, plant, or object in the room.', 'Odadaki en sevdiğin evcil hayvanı, bitkiyi veya nesneyi tanıt.'),
  ('What is the weather like outside your window?', 'Pencerenin dışında hava nasıl?'),
  ('Show us a sneaky peek of what you are having for lunch.', 'Öğle yemeğinde ne yediğine dair küçük bir ipucu göster.'),
  ('Show the most chaotic or messy spot near you right now.', 'Şu anda yakınındaki en dağınık veya karmaşık yeri göster.'),
  ('Do a quick 5-second face reveal with your current mood.', 'Şu anki ruh hâlini gösteren 5 saniyelik hızlı bir yüz çekimi yap.'),
  ('Show us the book or article you are currently reading.', 'Şu anda okuduğun kitabı veya makaleyi bize göster.'),
  ('Share your absolute favorite corner of your home.', 'Evinin en sevdiğin köşesini paylaş.'),
  ('Show us the most useless thing you bought recently.', 'Yakın zamanda satın aldığın en gereksiz şeyi bize göster.'),
  ('What is the last photo in your camera roll? Show it on screen!', 'Galerindeki son fotoğraf ne? Ekranda göster!'),
  ('Show us your favorite kitchen gadget or mug.', 'En sevdiğin mutfak aletini veya kupanı bize göster.'),
  ('Record a mini-tour of your room or office in 10 seconds.', 'Odanı veya ofisini 10 saniyede kısaca gezdir.'),
  ('Show us what you are working on or studying right now.', 'Şu anda üzerinde çalıştığın veya dersini yaptığın şeyi bize göster.'),
  ('What is your go-to snack when you are bored?', 'Sıkıldığında ilk tercih ettiğin atıştırmalık ne?'),
  ('Show us a hobby you are passionate about.', 'Tutkuyla yaptığın bir hobini bize göster.'),
  ('Record a 5-second silent scream or funny face.', '5 saniyelik sessiz bir çığlık veya komik bir yüz ifadesi kaydet.'),
  ('Show the coolest piece of art or poster on your wall.', 'Duvarındaki en havalı sanat eserini veya posteri göster.'),
  ('What does your neighborhood look like right now?', 'Mahallen şu anda nasıl görünüyor?'),
  ('Show us your shoes or footwear for today.', 'Bugün giydiğin ayakkabıları bize göster.'),
  ('What is one item you can''t leave the house without?', 'Evden çıkarken yanına almadan yapamadığın şey ne?'),
  ('Show us your fridge interior—no cleaning up first!', 'Buzdolabının içini bize göster—ama önce toparlamak yok!'),
  ('Show us a quick view of your commute or walk.', 'Yolculuğundan veya yürüyüşünden kısa bir görüntü göster.'),
  ('What is a hidden talent you have? Show us a hint of it.', 'Gizli yeteneğin ne? Bize küçük bir ipucu göster.'),
  ('Show the last text message you received (no names!).', 'Aldığın son mesajı göster (isimler görünmesin!).'),
  ('What is your current guilty pleasure TV show or movie?', 'Şu sıralar gizlice izlemekten keyif aldığın dizi veya film hangisi?'),
  ('Show us something that instantly makes you smile.', 'Seni anında gülümseten bir şeyi bize göster.'),
  ('What is the most comfortable spot you have sat in today?', 'Bugün oturduğun en rahat yer neresi?'),
  ('Show us a quick DIY project or something you built.', 'Kendin yaptığın küçük bir projeyi veya inşa ettiğin bir şeyi bize göster.'),
  ('What is your favorite piece of tech right now?', 'Şu anda en sevdiğin teknolojik ürün ne?'),
  ('Show us your keys and their keychain.', 'Anahtarlarını ve anahtarlığını bize göster.'),
  ('What is a song that is stuck in your head today?', 'Bugün aklına takılan şarkı hangisi?'),
  ('Show us your daily skincare or grooming routine setup.', 'Günlük cilt bakımı veya kişisel bakım düzenini bize göster.'),
  ('What is the oldest piece of clothing you still wear?', 'Hâlâ giydiğin en eski kıyafet hangisi?'),
  ('Show us your favorite local coffee shop or park.', 'En sevdiğin yerel kafeyi veya parkı bize göster.'),
  ('Record a quick snippet of your favorite evening activity.', 'En sevdiğin akşam aktivitesinden kısa bir bölüm kaydet.'),
  ('Show us your bag or backpack interior.', 'Çantanın veya sırt çantanın içini bize göster.'),
  ('What is something you are looking forward to this week?', 'Bu hafta heyecanla beklediğin şey ne?'),
  ('Show us the last thing you cooked or baked.', 'En son pişirdiğin veya fırında yaptığın şeyi bize göster.'),
  ('What is your favorite spot to think or relax?', 'Düşünmek veya rahatlamak için en sevdiğin yer neresi?'),
  ('Show us the view directly behind you right now.', 'Şu anda tam arkandaki manzarayı bize göster.'),
  ('What is the most colorful thing in your room?', 'Odandaki en renkli şey ne?'),
  ('Show us how you organize (or don''t organize) your shoes.', 'Ayakkabılarını nasıl düzenlediğini (veya düzenlemediğini) bize göster.'),
  ('Show us your current desktop wallpaper on your PC or phone.', 'Bilgisayarındaki veya telefonundaki mevcut duvar kâğıdını bize göster.'),
  ('What is a local spot you think everyone should visit?', 'Sence herkesin ziyaret etmesi gereken yerel bir mekân neresi?'),
  ('Show us a quick 5-second stretching routine.', 'Bize 5 saniyelik hızlı bir esneme rutini göster.'),
  ('What is your current energy level from 1 to 10? Show it!', 'Şu anki enerji seviyen 1 ile 10 arasında kaç? Göster!')
) AS localized("textEn", "textTr")
WHERE prompt."text" = localized."textEn";
